const body = $input.first().json.body || $input.first().json;
const action = (body.action || 'create').toLowerCase();
const job = body.job || body;

const esc = (val) => String(val ?? '').replace(/'/g, "''");
let sql = '';

if (action === 'delete') {
  sql = `DELETE FROM "Job_Postings" WHERE job_id = '${esc(job.job_id)}';`;
} else if (action === 'update') {
  sql = `UPDATE "Job_Postings" SET 
    job_title = '${esc(job.job_title)}',
    job_description = '${esc(job.job_description)}',
    required_skills = '${esc(job.required_skills)}',
    preferred_skills = '${esc(job.preferred_skills)}',
    required_experience = '${esc(job.required_experience)}',
    work_type = '${esc(job.work_type)}',
    benefits = '${esc(job.benefits)}',
    deadline = '${esc(job.deadline)}',
    status = '${esc(job.status || 'Open')}'
    WHERE job_id = '${esc(job.job_id)}';`;
} else {
  sql = `INSERT INTO "Job_Postings" (job_id, job_title, job_description, required_skills, preferred_skills, required_experience, work_type, benefits, deadline, status) VALUES (
    '${esc(job.job_id)}',
    '${esc(job.job_title)}',
    '${esc(job.job_description)}',
    '${esc(job.required_skills)}',
    '${esc(job.preferred_skills)}',
    '${esc(job.required_experience)}',
    '${esc(job.work_type)}',
    '${esc(job.benefits)}',
    '${esc(job.deadline)}',
    '${esc(job.status || 'Open')}'
  )
  ON CONFLICT (job_id) DO UPDATE SET
    job_title = EXCLUDED.job_title,
    job_description = EXCLUDED.job_description,
    required_skills = EXCLUDED.required_skills,
    preferred_skills = EXCLUDED.preferred_skills,
    required_experience = EXCLUDED.required_experience,
    work_type = EXCLUDED.work_type,
    benefits = EXCLUDED.benefits,
    deadline = EXCLUDED.deadline,
    status = EXCLUDED.status;`;
}

return [{ json: { sql, action, job_id: job.job_id } }];
